package com.example.starter.gas.model;

/**
 * 加注阀状态。
 * OPEN：正常加注；LOCKED：告警锁定，停止加注。
 */
public enum ValveState {
    OPEN,
    LOCKED
}

package com.example.starter.gas.model;

/**
 * 管网压力联动动作。
 * HOLD：压力合格不调节；RAISE：低于下限需升压；LOWER：高于上限需泄压。
 */
public enum PressureAction {
    HOLD,
    RAISE,
    LOWER
}

package com.example.starter.gas.model;

/**
 * 联动任务状态。
 * EXECUTING：执行中（同站同时刻唯一）；COMPLETED：已完成。
 */
public enum LinkageTaskStatus {
    EXECUTING,
    COMPLETED
}

package com.example.starter.gas.model;

/**
 * 联动任务类型：压力调节联动（同一事务内附带加注调整）。
 */
public enum LinkageTaskType {
    PRESSURE_REGULATION
}

package com.example.starter.gas.model;

/**
 * 日结状态。
 * SEALED：勾稽合格并封存（终态）；MANUAL：偏差超限转人工。
 */
public enum SettlementStatus {
    SEALED,
    MANUAL
}

package com.example.starter.gas.model;

/**
 * 站内事件类型。
 * ODOR_ALARM：浓度越限告警；VALVE_LOCKED：双人确认锁阀；VALVE_REOPENED：双人确认复开并解除告警；
 * LATE_DETECTION：封存后迟到检测；MANUAL_REVIEW：日结转人工。
 */
public enum EventKind {
    ODOR_ALARM,
    VALVE_LOCKED,
    VALVE_REOPENED,
    LATE_DETECTION,
    MANUAL_REVIEW
}

