package com.example.starter.gas.web;

import org.springframework.http.HttpStatus;

/**
 * 业务异常基类：携带 HTTP 状态码与错误码。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String errorCode;

    public ApiException(HttpStatus status, String errorCode, String message) {
        super(message);
        this.status = status;
        this.errorCode = errorCode;
    }

    public HttpStatus getStatus() {
        return status;
    }

    public String getErrorCode() {
        return errorCode;
    }
}

package com.example.starter.gas.web;

import org.springframework.http.HttpStatus;

/**
 * 同 requestId 异参数：返回 409，且不改变任何阀门/任务状态。
 */
public class IdempotencyConflictException extends ApiException {

    public IdempotencyConflictException(String message) {
        super(HttpStatus.CONFLICT, "IDEMPOTENCY_CONFLICT", message);
    }
}

package com.example.starter.gas.web;

import org.springframework.http.HttpStatus;

/**
 * 同站同时刻已有执行中联动任务：并发下达时唯一受理，落选方返回 409。
 */
public class TaskSlotConflictException extends ApiException {

    public TaskSlotConflictException(String message) {
        super(HttpStatus.CONFLICT, "LINKAGE_TASK_CONFLICT", message);
    }
}

package com.example.starter.gas.web;

import java.time.OffsetDateTime;

/**
 * 统一错误响应体。
 */
public record ErrorResponse(String errorCode, String message, OffsetDateTime timestamp) {
}

