package com.example.starter.gas.web.dto;

import com.fasterxml.jackson.annotation.JsonFormat;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.PositiveOrZero;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 运行监测（浓度+流量检测）请求。
 *
 * @param actualConsumeG 装置上报的本时段实际加臭剂消耗，单位 g；可空，缺省等于理论消耗
 */
public record DetectionRequest(
        @NotBlank String requestId,
        @NotBlank String stationCode,
        @NotNull @JsonFormat(pattern = "yyyy-MM-dd'T'HH:mm:ss") LocalDateTime detectedAt,
        @NotNull @Positive BigDecimal concentrationMg,
        @NotNull @PositiveOrZero BigDecimal flowM3,
        @PositiveOrZero BigDecimal actualConsumeG
) {
}

package com.example.starter.gas.web.dto;

import java.math.BigDecimal;

/**
 * 单次加注下发视图。
 *
 * @param doseGPerM3         投加比例，单位 g/m³
 * @param theoreticalConsumeG 理论消耗，单位 g
 * @param actualConsumeG      实际下发消耗，单位 g；锁阀期间为 0
 * @param valveLocked         下发时阀门是否锁定
 */
public record InjectionView(
        BigDecimal doseGPerM3,
        BigDecimal theoreticalConsumeG,
        BigDecimal actualConsumeG,
        boolean valveLocked
) {
}

package com.example.starter.gas.web.dto;

import com.fasterxml.jackson.annotation.JsonFormat;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 运行监测响应。
 *
 * @param consecutiveViolations 截至本次的连续越限次数（复开清零、合格清零）
 * @param alarmTriggered        本次是否恰好连续 2 次越限而触发告警并锁阀
 * @param acceptedAsLate        结算日已封存时仅登记迟到事件，不落检测数据
 */
public record DetectionResponse(
        String requestId,
        String stationCode,
        @JsonFormat(pattern = "yyyy-MM-dd'T'HH:mm:ss") LocalDateTime detectedAt,
        BigDecimal concentrationMg,
        BigDecimal targetMg,
        BigDecimal lowerMg,
        BigDecimal upperMg,
        boolean inRange,
        int consecutiveViolations,
        boolean alarmTriggered,
        String valveState,
        boolean alarmActive,
        boolean acceptedAsLate,
        InjectionView injection,
        boolean idempotentReplayed
) {
}

