        assertThat(countOf("concentration_detection", "request_id = ?", "D-LATE")).isZero();
        assertThat(countOf("flow_reading", "request_id = ?", "D-LATE")).isZero();
        assertThat(countOf("odorant_injection", "source_request_id = ?", "D-LATE")).isZero();
