        if (!existing.fingerprint().equals(fingerprint)) {
            return new Attempt.DiffAttempt();
        }
        return new Attempt.SameAttempt(existing.responseBody());
    }

    /** 独立事务插入占位；唯一键冲突返回 false，事务仅回滚该插入。 */
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public boolean tryInsertPending(String requestId, String requestType, String fingerprint) {
        try {
            repo.insertPendingIdempotent(requestId, requestType, fingerprint);
            return true;
        } catch (DuplicateKeyException ex) {
            return false;
        }
    }

    /**
     * 同键同参重放且首发事务尚未提交时，轮询等待首次响应快照出现。
     */
    public String awaitFirstResponse(String requestId) {
        long deadline = System.currentTimeMillis() + WAIT_TIMEOUT_MS;
        while (System.currentTimeMillis() < deadline) {
            GasRepository.IdempotentRow row = readFresh(requestId);
            if (row != null && row.responseBody() != null) {
                return row.responseBody();
            }
            try {
                Thread.sleep(POLL_INTERVAL_MS);
            } catch (InterruptedException ex) {
                Thread.currentThread().interrupt();
                throw new IllegalStateException("等待首次响应时被中断", ex);
            }
        }
        throw new IllegalStateException("等待 requestId=" + requestId + " 首次响应超时");
    }

    /** 业务事务回滚时，在独立事务中清理占位，避免后续请求误判为重放。 */
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void abort(String requestId) {
        repo.deleteIdempotent(requestId);
    }

    /** 独立事务读取，轮询期间每次读取都是新事务，可看到首发已提交数据。 */
    @Transactional(propagation = Propagation.REQUIRES_NEW, readOnly = true)
    public GasRepository.IdempotentRow readFresh(String requestId) {
        return repo.findIdempotent(requestId);
    }
}

